# -*- coding: utf-8 -*-
import json, os
OUT = r"E:\webexcel\output\json_v2"
os.makedirs(OUT, exist_ok=True)

def save(vid, data):
    p = os.path.join(OUT, vid + ".json")
    open(p, "w", encoding="utf-8").write(json.dumps(data, ensure_ascii=False, indent=2))
    print("saved", p, "ct:", len(data["cong_thuc"]), "qt:", len(data["thuat_toan_quy_trinh"]), "q:", len(data["cau_hoi"]))

def Q(i, cau, A, B, C, D, da, gt, chu_de, do_kho, ts):
    assert da in ("A","B","C","D")
    return {"id": i, "cau": cau, "A": A, "B": B, "C": C, "D": D, "dap_an": da, "giai_thich": gt, "chu_de": chu_de, "do_kho": do_kho, "timestamp": ts}

def S(buoc, thao_tac, phim_tat="", luu_y=""):
    return {"buoc": buoc, "thao_tac": thao_tac, "phim_tat": phim_tat, "luu_y": luu_y}

