for i,(t,a,b,c,d,da,gt,cd,dk,ts) in enumerate(q20_raw,1):
    opts=[a,b,c,d]
    if i%4==2: opts=[b,a,d,c]; da={"A":"B","B":"A","C":"D","D":"C"}[da]
    elif i%4==3: opts=[c,d,a,b]; da={"A":"C","B":"D","C":"A","D":"B"}[da]
    elif i%4==0: opts=[d,c,b,a]; da={"A":"D","B":"C","C":"B","D":"A"}[da]
    q20.append(Q(i,t,opts[0],opts[1],opts[2],opts[3],da,gt,cd,dk,ts))
